/** Headless check that polymorphic Actor dispatch matches the old instanceof logic. */
public class DispatchTest
{
    static boolean ok = true;
    static void check(String label, boolean cond) {
        if (!cond) { ok = false; System.out.println("  FAIL: " + label); }
    }

    public static void main(String[] args)
    {
        Field field = new Field(20, 20);
        Lion lion = new Lion(false, field, new Location(0, 0));      // Animal, diurnal
        Hyena hyena = new Hyena(false, field, new Location(1, 1));   // Animal, nocturnal
        Grass grass = new Grass(false, field, new Location(2, 2));   // Plant
        Lake lake = new Lake(false, field, new Location(3, 3));      // WaterSources
        Weather weather = new Weather(null);                        // non-physical actor
        Covid covid = new Covid(field);                             // non-physical actor

        // --- onRain: organisms +5 water, water sources +10 volume ---
        int lw = lion.getWaterLevel(), gw = grass.getWaterLevel(), lv = lake.getVolume();
        lion.onRain(); grass.onRain(); lake.onRain(); weather.onRain(); covid.onRain();
        check("lion rain +5", lion.getWaterLevel() == lw + 5);
        check("grass rain +5", grass.getWaterLevel() == gw + 5);
        check("lake rain +10", lake.getVolume() == lv + 10);

        // --- onFog: plant +2 water, water +2 volume, animal sleeps (no water change) ---
        lw = lion.getWaterLevel(); gw = grass.getWaterLevel(); lv = lake.getVolume();
        lion.onFog(); grass.onFog(); lake.onFog();
        check("lion fog -> sleep, water unchanged", lion.getWaterLevel() == lw);
        check("grass fog +2", grass.getWaterLevel() == gw + 2);
        check("lake fog +2", lake.getVolume() == lv + 2);

        // --- onHeatwave: organisms water/2, water sources volume/2 ---
        lw = lion.getWaterLevel(); gw = grass.getWaterLevel(); lv = lake.getVolume();
        lion.onHeatwave(); grass.onHeatwave(); lake.onHeatwave();
        check("lion heatwave /2", lion.getWaterLevel() == lw / 2);
        check("grass heatwave /2", grass.getWaterLevel() == gw / 2);
        check("lake heatwave /2", lake.getVolume() == lv / 2);

        // --- canActNow: diurnal acts by day, nocturnal acts by night, others always ---
        check("lion day", lion.canActNow(false) && !lion.canActNow(true));
        check("hyena night", hyena.canActNow(true) && !hyena.canActNow(false));
        check("grass always acts", grass.canActNow(true) && grass.canActNow(false));
        check("weather always acts", weather.canActNow(true));
        check("covid always acts", covid.canActNow(false));

        // --- isExpired: dead organism / empty water leave; others persist ---
        check("live lion not expired", !lion.isExpired());
        check("filled lake not expired", !lake.isExpired());
        check("weather never expires", !weather.isExpired());
        lion.setDead();
        check("dead lion expired", lion.isExpired());

        System.out.println(ok
            ? "PASS: polymorphic dispatch reproduces the old per-type behaviour."
            : "FAIL: see above.");
    }
}

